-- Initial legacy account and notification schema, without accounts or credentials.
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE TYPE "public"."donation_status_enum" AS ENUM ('AVAILABLE','CLAIMED','PICKED_UP','DELIVERED','EXPIRED');
CREATE TYPE "public"."flagged_donation_status_enum" AS ENUM ('FLAGGED','APPROVED','REJECTED','ESCALATED');
CREATE TYPE "public"."support_ticket_priority_enum" AS ENUM ('LOW','MEDIUM','HIGH','CRITICAL');
CREATE TYPE "public"."support_ticket_status_enum" AS ENUM ('OPEN','IN_PROGRESS','RESOLVED','CLOSED');
CREATE TYPE "public"."user_role_enum" AS ENUM ('DONOR','NGO','VOLUNTEER','ADMIN');
CREATE TABLE "public"."donation" ("id" uuid DEFAULT uuid_generate_v4() NOT NULL,"name" character varying NOT NULL,"donorName" character varying NOT NULL,"description" character varying,"hygiene" text,"donorTrustScore" double precision,"foodType" character varying NOT NULL,"quantity" numeric(10,2) NOT NULL,"unit" character varying NOT NULL,"preparationTime" character varying NOT NULL,"latitude" double precision NOT NULL,"longitude" double precision NOT NULL,"address" character varying,"imageUrls" text,"specialInstructions" character varying,"status" donation_status_enum DEFAULT 'AVAILABLE'::donation_status_enum NOT NULL,"donorId" uuid NOT NULL,"claimedById" character varying,"volunteerId" character varying,"expiryTime" timestamp without time zone,"pickedUpAt" timestamp without time zone,"deliveredAt" timestamp without time zone,"createdAt" timestamp without time zone DEFAULT now() NOT NULL);
CREATE TABLE "public"."donation_feedback" ("id" uuid DEFAULT uuid_generate_v4() NOT NULL,"rating" integer NOT NULL,"comment" text,"donationId" uuid NOT NULL,"ngoId" uuid NOT NULL,"createdAt" timestamp without time zone DEFAULT now() NOT NULL);
CREATE TABLE "public"."flagged_donation" ("id" uuid DEFAULT uuid_generate_v4() NOT NULL,"donationId" character varying NOT NULL,"donationName" character varying NOT NULL,"reportedByUserId" character varying NOT NULL,"reportedByEmail" character varying NOT NULL,"reason" text NOT NULL,"status" flagged_donation_status_enum DEFAULT 'FLAGGED'::flagged_donation_status_enum NOT NULL,"adminNote" character varying,"createdAt" timestamp without time zone DEFAULT now() NOT NULL,"updatedAt" timestamp without time zone DEFAULT now() NOT NULL);
CREATE TABLE "public"."samrit_record" ("id" uuid DEFAULT uuid_generate_v4() NOT NULL,"kind" character varying NOT NULL,"payload" jsonb NOT NULL,"createdAt" timestamp without time zone DEFAULT now() NOT NULL,"updatedAt" timestamp without time zone DEFAULT now() NOT NULL);
CREATE TABLE "public"."support_ticket" ("id" uuid DEFAULT uuid_generate_v4() NOT NULL,"userId" character varying NOT NULL,"userEmail" character varying NOT NULL,"userName" character varying NOT NULL,"subject" character varying NOT NULL,"description" text NOT NULL,"status" support_ticket_status_enum DEFAULT 'OPEN'::support_ticket_status_enum NOT NULL,"priority" support_ticket_priority_enum DEFAULT 'MEDIUM'::support_ticket_priority_enum NOT NULL,"adminNote" character varying,"createdAt" timestamp without time zone DEFAULT now() NOT NULL,"updatedAt" timestamp without time zone DEFAULT now() NOT NULL);
CREATE TABLE "public"."user" ("id" uuid DEFAULT uuid_generate_v4() NOT NULL,"email" character varying NOT NULL,"password" character varying NOT NULL,"role" user_role_enum DEFAULT 'DONOR'::user_role_enum NOT NULL,"isVerified" boolean DEFAULT false NOT NULL,"isActive" boolean DEFAULT true NOT NULL,"name" character varying NOT NULL,"organizationName" character varying,"organizationType" character varying,"phone" character varying,"address" character varying,"latitude" double precision,"longitude" double precision,"dailyIntakeCapacity" double precision,"currentIntakeLoad" double precision DEFAULT '0'::double precision NOT NULL,"capacityUnit" character varying,"certificateUrl" character varying,"vehicleType" character varying,"vehicleNumber" character varying,"isAvailable" boolean DEFAULT false NOT NULL,"trustScore" double precision DEFAULT '0'::double precision NOT NULL,"karmaPoints" integer DEFAULT 0 NOT NULL,"badges" text DEFAULT ''::text NOT NULL,"createdAt" timestamp without time zone DEFAULT now() NOT NULL,"updatedAt" timestamp without time zone DEFAULT now() NOT NULL,"transportCapabilities" text);
CREATE TABLE "public"."user_notification" ("id" uuid DEFAULT uuid_generate_v4() NOT NULL,"userId" uuid NOT NULL,"title" character varying NOT NULL,"message" text NOT NULL,"type" character varying DEFAULT 'new_food_nearby'::character varying NOT NULL,"read" boolean DEFAULT false NOT NULL,"createdAt" timestamp without time zone DEFAULT now() NOT NULL);
ALTER TABLE "public"."donation" ADD CONSTRAINT "PK_25fb5a541964bc5cfc18fb13a82" PRIMARY KEY (id);
ALTER TABLE "public"."donation_feedback" ADD CONSTRAINT "PK_b7b9c007de7037e4134a73282cf" PRIMARY KEY (id);
ALTER TABLE "public"."flagged_donation" ADD CONSTRAINT "PK_d79cb8c38957ef0be24ef88fc87" PRIMARY KEY (id);
ALTER TABLE "public"."samrit_record" ADD CONSTRAINT "PK_9d42309f9db26be29076bb1fb6a" PRIMARY KEY (id);
ALTER TABLE "public"."support_ticket" ADD CONSTRAINT "PK_506b4b9f579fb3adbaebe3950c2" PRIMARY KEY (id);
ALTER TABLE "public"."user" ADD CONSTRAINT "PK_cace4a159ff9f2512dd42373760" PRIMARY KEY (id);
ALTER TABLE "public"."user" ADD CONSTRAINT "UQ_e12875dfb3b1d92d7d7c5377e22" UNIQUE (email);
ALTER TABLE "public"."user_notification" ADD CONSTRAINT "PK_8840aac86dec5f669c541ce67d4" PRIMARY KEY (id);
ALTER TABLE "public"."donation" ADD CONSTRAINT "FK_5f345add82fd6c572f306449cb7" FOREIGN KEY ("donorId") REFERENCES "user"(id);
ALTER TABLE "public"."donation_feedback" ADD CONSTRAINT "FK_9dcd925be399bd437667d2349c1" FOREIGN KEY ("donationId") REFERENCES donation(id) ON DELETE CASCADE;
ALTER TABLE "public"."donation_feedback" ADD CONSTRAINT "FK_2366263fae2c67bb5d4f2ad6c5e" FOREIGN KEY ("ngoId") REFERENCES "user"(id) ON DELETE CASCADE;
ALTER TABLE "public"."user_notification" ADD CONSTRAINT "FK_dce2a8927967051c447ae10bc8b" FOREIGN KEY ("userId") REFERENCES "user"(id) ON DELETE CASCADE;
